check('the email is logged', (int) val("SELECT COUNT(*) FROM {email_log} WHERE event='pdf.export' AND status='sent'") === 1); putenv('MFNC_MAIL_DRYRUN'); set_setting('email_enabled', '0'); throws(fn() => do_pdf_email($upo), 'not set up', 'emailing explains when email is off');
$pf = $CU('pdf-free@x.test'); $upf = one('SELECT * FROM {users} WHERE id=?', [$pf]); $_POST = ['kind' => 'report', 'month' => $mo]; throws(fn() => do_pdf_email($upf), 'paid plan', 'a free-plan user cannot email a PDF'); throws(fn() => do_pdf_link($upf), 'paid plan', 'or make a link');
